const dependencies = (): string => {
  const at = source.indexOf(call)
  expect(at, `${path} no longer calls ${call}`).toBeGreaterThan(-1)

  const open = source.indexOf('{', at)
  expect(open, `${path}: ${call} has no argument object`).toBeGreaterThan(-1)
  let depth = 0
  for (let i = open; i < source.length; i += 1) {
    const ch = source[i]
    if (ch === '{') depth += 1
    else if (ch === '}') {
      depth -= 1
      if (depth === 0) return source.slice(open, i + 1)
    }
  }
  throw new Error(`${path}: could not find the end of the dependency object`)
}

/** The `unitReference` property declaration, whitespace collapsed. */
const declaration = (): string => {
  const schemaAt = source.indexOf('function responseSchema')
  const start = schemaAt === -1 ? -1 : source.indexOf('unitReference:', schemaAt)
  if (start === -1) return ''

  // To the end of the property's own object literal, which is where its `}`
  // closes -- not the first `}` in the file after it.
  let depth = 0
  for (let i = start; i < source.length; i += 1) {
    const ch = source[i]
    if (ch === '{') depth += 1
    else if (ch === '}') {
      depth -= 1
      if (depth === 0) return source.slice(start, i + 1).replace(/\s+/g, ' ')
    }
  }
  return ''
}

